/* ───── tiny reusable button ───── */
function Btn({ gold, children, style, onClick, href, ...props }) {
  const base = {
    display: "inline-flex", alignItems: "center", justifyContent: "center",
    fontFamily: "'DM Sans', sans-serif", fontWeight: 700,
    fontSize: 13, letterSpacing: 2, textTransform: "uppercase",
    border: "none", cursor: "pointer", textDecoration: "none",
    transition: "all 0.35s ease",
  };
  const goldStyle = {
    ...base,
    background: `linear-gradient(135deg, ${GOLD}, ${GOLD_LIGHT}, ${GOLD})`,
    backgroundSize: "200% 200%", color: "#000",
    padding: "16px 40px",
  };
  const outlineStyle = {
    ...base,
    background: "transparent", color: "#fff",
    border: `1px solid ${BORDER}`, padding: "16px 40px",
  };
  const handleClick = (e) => {
    if (onClick) { e.preventDefault(); onClick(e); }
    else if (href && href.startsWith("#")) {
      e.preventDefault();
      const el = document.getElementById(href.slice(1));
      if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };
  return <a href={href || "#"} {...props} onClick={handleClick} style={{ ...(gold ? goldStyle : outlineStyle), ...style }}>{children}</a>;
}

